  for(let i=0;i<n;i++){
    entries[i]={id:i, marker:(rnd()%7)};
    names[i]=words[rnd()%words.length] + String(rnd()%19);
    const r=rnd()%16;
    bases[i]=r===0?NaN:r===1?Infinity:r===2?-Infinity:((rnd()%2001)-1000)/1000;
  }
  const search=words[rnd()%words.length];
  const tr=rnd()%12;
  const threshold=tr===0?NaN:tr===1?Infinity:tr===2?-Infinity:((rnd()%1601)-800)/1000;
  const ta=[],tb=[];
  const a=oldCollect(entries,names,search,threshold,bases,ta);
  const b=newCollect(entries,names,search,threshold,bases,tb);
  const norm=x=>x.map(v=>({id:v.entry.id,score:Number.isNaN(v.score)?"NaN":String(v.score)}));
  if(JSON.stringify(norm(a))!==JSON.stringify(norm(b))) process.exit(10);
